function registerAppTool(target,name,options,handler){
  operationHandlers.set(name,{options,handler});
  const metadata={...options._meta,ui:{...options._meta?.ui,...(!compactTools.has(name)?{visibility:['app']}:{})}};
  return registerSdkTool(target,name,{...options,_meta:metadata},compactTools.has(name)?(...args)=>responseContext.run({...responseContext.getStore(),singleCopy:true},()=>handler(...args)):handler);
}
const VERSION = packageInfo.version;
