registerAppTool(server,'archive_team',{description:'Only after explicit user instruction: archive the current completed native team, preserve acceptance and all history, and free the project for a new team. Requires Leader final acceptance, no pending plan changes/reservations, and verified idle native members. Stable UUID safely replays an uncertain save. Never starts/stops members or archives Codex chats.',inputSchema:{...editTeam,requestId:z.string().uuid(),reason:z.string().min(1).max(1000),source:z.enum(['panel-user-action','leader-recorded-user-instruction'])},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{resourceUri:URI,visibility:['app','model']}}},guarded(async(a,e)=>projectTeams.archive(await assertCurrentTeam(e,a.teamId),await currentProject(e),a)));
