registerAppTool(server,'record_team_navigation',{description:'记录导航结果。面板 openLink 返回无错误后只能记录 host-accepted，表示宿主接收链接，不证明会话呈现或轮次定位。旧 host-tool 请求由 Leader 按真实工具回执记录 opened/failed。',inputSchema:{...teamId,requestId:z.string().uuid(),status:z.enum(['host-accepted','opened','failed']),note:z.string().min(1).max(2000)},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>navigation.record(await assertCurrentTeam(e,a.teamId),await currentProject(e),a)));
for(const [name,method,title] of [['start_team','start','开始执行计划'],['pause_team_dispatch','pause','暂停新任务派发'],['integrate_team','integrate','将全部已验收候选写回项目'],['reconcile_team','reconcile','核对已保存的执行状态，不恢复轮次'],['recover_team_integration','recoverIntegration','回退中断的写回；保留外部新改动，不自动重新写回']])registerAppTool(server,name,{title,description:`${title}。原生团队由当前主会话控制；开始仅允许 Leader 派发，不启动后台调度。仅在用户通过当前对话明确授权后执行；旧版本号请求拒绝，未知状态不自动重试。`,inputSchema:editTeam,annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:true},_meta:{ui:{resourceUri:URI,visibility:['app','model']}}},guarded(async(args,extra)=>({kind:'team-detail',...await route(method,await assertCurrentTeam(extra,args.teamId),args.teamId,args.revision)})));
registerAppTool(server,'read_team_model_catalog',{title:'宿主模型目录',description:'从当前安装的 Codex model/list 读取实际模型与支持的思考档位。短时缓存，不启动模型；不可用时明确报错，不使用编造的模型列表。',inputSchema:{},annotations:readOnly,_meta:{ui:{visibility:['app','model']}}},guarded(async(_,e)=>{await currentProject(e);return {kind:'team-model-catalog',...await modelCatalog.read()};}));
registerAppTool(server,'stop_team',{title:'停止团队',description:'暂停派发并记录 stopping，返回全部原生成员（包括初始化轮次）与未知预留。Leader 执行实际中断并 reconcile_team_stop 后才能标记 halted。保存停止请求不等于已停止。',inputSchema:{...editTeam,reason:z.string().min(1).max(2000),requestId:z.string().uuid()},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:true},_meta:{ui:{resourceUri:URI,visibility:['app','model']}}},guarded(async(a,e)=>({kind:'team-detail',...await (async()=>{const o=await assertCurrentTeam(e,a.teamId),t=await engine.store.get(a.teamId,o);return t.mode==='host-leader'?leader.stop(o,a.teamId,a.revision,a):route('stop',o,a.teamId,a.revision,a);})()})));
registerAppTool(server,'reconcile_team_stop',{description:'只核实停止请求，宿主最新轮次未确认结束或预留未知时保持 stopping。unstartedTaskIds 仅限 Leader 已核实尚未送达宿主的绑定预留，必须写实际核对证据；未绑定预留先核实并 release。',inputSchema:{...editTeam,unstartedTaskIds:z.array(id).max(8).default([]),note:z.string().max(2000).default('')},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>({kind:'team-detail',...await leader.reconcileStop(await assertCurrentTeam(e,a.teamId),a.teamId,a.revision,a)})));
registerAppTool(server,'resume_team',{title:'恢复团队',description:'仅从已核实 halted 恢复，必须记录原因。只重试 retryTaskIds 中明确选中的停止/失败任务，保留全部历史和预算；不恢复已取消任务，不直接启动模型。',inputSchema:{...editTeam,reason:z.string().min(1).max(2000),requestId:z.string().uuid(),retryTaskIds:z.array(id).max(40).default([])},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{resourceUri:URI,visibility:['app','model']}}},guarded(async(a,e)=>({kind:'team-detail',...await leader.resume(await assertCurrentTeam(e,a.teamId),a.teamId,a.revision,a)})));
registerAppTool(server,'amend_team_task_contract',{description:'Leader 修订未通过验收的任务合同，记录原因、旧值、新值和版本，使下游旧证据失效并暂停派发。运行中须先停止并 settle，已提交须先 rework；通过验收的合同冻结。扩大范围另走 propose_team_change，禁止以修订降低或绕过用户验收要求。',inputSchema:{...editTeam,taskId:id,requestId:z.string().uuid(),reason:z.string().min(1).max(3000),patch:z.object({goal:z.string().min(1).max(3000).optional(),acceptance:z.string().min(1).max(3000).optional(),acceptanceCriteria:criteriaSchema.optional(),contract:contractSchema.optional()}).strict()},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>({kind:'team-detail',...await leader.amendContract(await assertCurrentTeam(e,a.teamId),a.teamId,a.revision,a)})));
registerAppTool(server,'message_team_member',{description:'原生团队持久保存消息并返回 Leader 原生发送提示；requestId 重试去重。保存不是送达，未知结果不自动重发。旧团队沿用其执行端。',inputSchema:{...editTeam,taskId:id,text:z.string().min(1).max(3000),requestId:z.string().uuid().optional()},annotations:{readOnlyHint:false,openWorldHint:true},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>({kind:'team-detail',...await route('message',await assertCurrentTeam(e,a.teamId),a.teamId,a.revision,a.taskId,a.text,a.requestId)})));
registerAppTool(server,'edit_team_task',{description:'修改尚未开工任务的分配、优先级或依赖，保留历史并重新校验任务图。',inputSchema:{...editTeam,taskId:id,patch:z.object({memberId:id.optional(),priority:z.number().int().min(1).max(5).optional(),dependencies:z.array(z.object({taskId:id,when:z.enum(['submitted','accepted'])})).optional()})},annotations:{readOnlyHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>({kind:'team-detail',...await route('edit',await assertCurrentTeam(e,a.teamId),a.teamId,a.revision,a.taskId,a.patch)})));
registerAppTool(server,'add_team_tasks',{description:'团队组建确认后，Leader 在已确认目标和职责内拆分或追加具体任务，无需逐项确认；保留历史和独立审查。目标或范围实质扩大必须 scopeChange=true 并写 note，暂存为待确认提案；分配给待批准新岗位的任务也会暂存。语义范围由 Leader 核对，不可自行推定用户已批准扩展。',inputSchema:{...editTeam,tasks:planSchema.shape.tasks,scopeChange:z.boolean().default(false),note:z.string().max(3000).optional()},annotations:{readOnlyHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>({kind:'team-detail',...await route('addTasks',await assertCurrentTeam(e,a.teamId),a.teamId,a.revision,a.tasks,{scopeChange:a.scopeChange,note:a.note})})));
registerAppTool(server,'cancel_team_task',{description:'取消尚未开工的任务及其尚未开工下游，保留历史；已有执行记录时拒绝伪装取消。',inputSchema:{...editTeam,taskId:id,note:z.string().min(1).max(1000)},annotations:{readOnlyHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>({kind:'team-detail',...await route('cancel',await assertCurrentTeam(e,a.teamId),a.teamId,a.revision,a.taskId,a.note)})));
registerAppTool(server,'rework_team_task',{description:'用户明确要求返工时调用；保留所有历史和预算，使下游结论失效。仍运行或未知的相关成员必须先停止并核对。不会自动开工。',inputSchema:{...editTeam,taskId:id,note:z.string().min(1).max(2000)},annotations:{readOnlyHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>({kind:'team-detail',...await route('rework',await assertCurrentTeam(e,a.teamId),a.teamId,a.revision,a.taskId,a.note)})));

