const checkpointText=z.string().trim().min(1).max(2000);
registerAppTool(server,'read_team_handoff',{description:'只读当前任务的目标、职责、前置证据和最新检查点，明确历史轮次；不启动或恢复成员。',inputSchema:{...teamId,taskId:id},annotations:readOnly,_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const {team,handoff}=await leader.handoff(await assertCurrentTeam(e,a.teamId),a.teamId,a.taskId);return {kind:'team-handoff',team:{id:team.id,revision:team.revision,projectPath:team.projectPath,leaderThreadId:team.leaderThreadId},handoff};}));
const nativeTool=(name,description,inputSchema,fn)=>registerAppTool(server,name,{description,inputSchema,annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const o=await assertCurrentTeam(e,a.teamId),t=await engine.store.get(a.teamId,o),current=await projectTeams.current(o,{cwd:t.projectPath});if(current&&current.id!==a.teamId&&!['settle_team_task','release_team_reservation','reconcile_team_message'].includes(name))throw new Error('Historical team is read-only; use the project’s current team');assertPlanExecutable(t);await modelCatalog.freeze(a.members,await currentProject(e));const data=await fn(a,o);return name==='advance_team_workflow'?advancementResponse(data,a.view):{kind:'team-detail',...data};}));
nativeTool('add_team_members','向当前项目的固定团队追加岗位，保留原成员、原生线程、正在执行的任务与历史。传稳定 requestId 重试去重；总人数最多 8。返回新岗位的初始化提示，由 Leader 创建并绑定对应原生 subagent，完成后用 add_team_tasks 分配任务。有计划确认记录的团队先暂存岗位变更，用户确认前不会创建或初始化新岗位；原成员继续工作。',{...editTeam,members:z.array(memberSchema).min(1).max(8),requestId:z.string().uuid()},(a,o)=>leader.addMembers(o,a.teamId,a.revision,a.members,a.requestId,{reviewExpansion:true}));
nativeTool('reassign_team_task','安全改派待执行或阻塞任务，保留每轮执行者、消息、检查点和用量历史。运行中先由 Leader 停止并 settle；已提交或验收任务先显式 rework。目的成员必须保有独立审查和写入范围约束。不会启动、停止模型或重置重试预算。稳定 requestId 去重。',{...editTeam,taskId:id,memberId:id,note:z.string().min(1).max(3000),requestId:z.string().uuid()},(a,o)=>leader.reassign(o,a.teamId,a.revision,a.taskId,a.memberId,a.note,a.requestId));
nativeTool('remove_team_member','移除已确认空闲且没有未完成任务的固定成员；保留其原生线程及全部历史，释放活跃岗位名额。先改派或完成未结束任务，宿主最新轮次未知时拒绝移除。工具不删除或中断原生线程。稳定 requestId 去重；移除后成员 ID 不能重用。',{...editTeam,memberId:id,note:z.string().min(1).max(3000),requestId:z.string().uuid()},(a,o)=>leader.removeMember(o,a.teamId,a.revision,a.memberId,a.note,a.requestId));
registerAppTool(server,'update_team_member_goal',{description:'人工调整已组建团队的角色职责/目标；只影响后续派发，已有任务保留原角色目标快照、任务约定及执行身份。要求当前目标版本和稳定 requestId，保留完整修改历史。直接保存，不发消息、停止成员或启动模型。',inputSchema:{...editTeam,memberId:id,goal:z.string().trim().min(1).max(2000),goalRevision:z.number().int().positive(),requestId:z.string().uuid(),note:z.string().trim().min(1).max(1000),source:z.enum(['panel-user-action','leader-recorded-user-instruction']).default('leader-recorded-user-instruction')},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{
 const o=await assertCurrentTeam(e,a.teamId),t=await leader.native(o,a.teamId),current=await projectTeams.current(o,{cwd:t.projectPath});if(current&&current.id!==t.id)throw new Error('历史团队只读');return leader.updateMemberGoal(o,a.teamId,a.revision,a);
}));
registerAppTool(server,'query_team_tasks',{description:'按任务号、文字、状态或成员分页查询任务摘要与当前轮次；不返回历史提示、交付或日志。按选定任务使用 read_team_context(view=evidence) 读取原始证据，不启动成员。',inputSchema:{...teamId,query:z.string().max(200).default(''),status:z.string().max(30).optional(),memberId:id.optional(),offset:z.number().int().min(0).default(0),limit:z.number().int().min(1).max(200).default(50),cursor:z.string().max(2000).optional()},annotations:readOnly,_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const o=await assertCurrentTeam(e,a.teamId),t=await engine.store.get(a.teamId,o);return {kind:'team-query',teamId:t.id,revision:t.revision,...taskQuery(t,a)};}));
registerAppTool(server,'export_team_report',{description:'导出当前项目团队的公开任务、交付和用量报告；无隐藏推理、账号凭据或跨项目记录。',inputSchema:{...teamId,format:z.enum(['markdown','json']).default('markdown')},annotations:readOnly,_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const d=await leader.read(await assertCurrentTeam(e,a.teamId),a.teamId);return {kind:'team-export',...exportTeam(d.team,{format:a.format,runs:d.runs,usage:d.usage})};}));
registerAppTool(server,'read_team_recovery',{description:'读取原团队、成员与任务的恢复包，观察真实线程；不恢复模型、不换成员、不把历史线程冒充可控句柄。',inputSchema:teamId,annotations:readOnly,_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const t=await engine.store.get(a.teamId,await assertCurrentTeam(e,a.teamId));return {kind:'team-recovery',...await recoveryPacket(t,leader.observer)};}));
registerAppTool(server,'read_project_team_takeover',{description:'查看当前项目原团队的接续边界及交接；跨 Leader 不伪造宿主接管，不另建团队。',inputSchema:{},annotations:readOnly,_meta:{ui:{visibility:['app','model']}}},guarded(async(_,e)=>{const c=await currentProject(e),index=await projectTeams.registry.read(),entry=index.projects[projectTeams.key(c)];if(!entry)return {kind:'team-takeover',status:'no-team'};const t=await engine.store.get(entry.teamId,entry.ownerId);if(t.projectPath!==c.cwd)throw new Error('Project identity mismatch');return {kind:'team-takeover',...takeoverBoundary(t,c.threadId)};}));
nativeTool('record_team_recovery_control','记录 Leader 对原成员实际调用原生工具的结果，失去控制能力时暂停派发，不能用读取成功冒充控制成功。',{...editTeam,memberId:id,threadId:z.string().min(1),status:z.enum(['available','unavailable']),tool:z.string().min(1).max(100),note:z.string().min(1).max(2000)},async(a,o)=>{await engine.store.update(a.teamId,o,a.revision,t=>recordRecoveryControl(t,a));return leader.receipt(o,a.teamId);});
nativeTool('configure_team_policy','调整预算和修复额度。提高预算或自动执行额度时先暂存变更提案，用户确认后才应用；降低额度沿用授权。',{...editTeam,policy:policySchema},(a,o)=>leader.configurePolicy(o,a.teamId,a.revision,a.policy,{reviewExpansion:true}));
nativeTool('advance_team_workflow','一次接收终态，审核通过且插件校验通过后直接登记验收并解锁依赖；Leader 仅处理审查异常与最终结项。默认返回最小处理回执、当前动作和完整派发包，可直接继续或等待，不必再读团队；view=summary 兼容旧摘要。复用有效证据，不重审或重跑相同测试；返回派发包后仍使用原生成员工具，不启动后台协调者。',{...editTeam,view:z.enum(['coordination','summary']).default('coordination'),settleCompleted:z.boolean().default(true),dispatchReady:z.boolean().default(false),decisions:z.array(z.object({taskId:id,attemptId:z.string().uuid(),decision:z.enum(['accept','rework']),note:z.string().min(1).max(2000),nonValidationFailures:z.array(z.object({commandIndex:z.number().int().min(0),reason:z.string().min(1).max(2000)})).max(30).default([]),deferredChecks:z.array(z.object({checkIndex:z.number().int().min(0),reason:z.string().min(1).max(2000)})).max(30).default([])})).max(8).default([])},(a,o)=>leader.advance(o,a.teamId,a.revision,a));
registerAppTool(server,'save_team_profile',{description:'保存可复用的岗位、模型路由与任务模板；不启动成员，不改现有团队身份。',inputSchema:{name:id,taskPlanning:z.enum(['seed','leader']).default('seed'),constraints:z.string().max(6000).default(''),plan:planSchema.extend({tasks:planSchema.shape.tasks.optional()}),policy:policySchema.optional(),note:z.string().max(2000).optional(),expectedUpdatedAt:z.string().optional()},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{await currentProject(e);return {kind:'team-profile',profile:await profiles.save(a.name,a.plan,a.policy,a.note,a)};}));
registerAppTool(server,'read_team_profiles',{description:'读取已保存团队模板，不启动成员。',inputSchema:{name:id.optional()},annotations:readOnly,_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{await currentProject(e);return {kind:'team-profiles',profiles:await profiles.read(a.name)};}));
registerAppTool(server,'plan_team_from_profile',{description:'按用户选择的模板组建或复用当前项目固定团队。新团队只确认目标、成员和职责，确认后 Leader 按模板约束拆分具体任务与独立审查；不要求组建时确认任务图。已有团队不替换成员。',inputSchema:{...approvalFields,name:id,maxParallel:z.number().int().min(1).max(8).default(3),goal:z.string().min(8).max(2000),execute:z.boolean().default(false)},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const p=await profiles.read(a.name),o=owner(e),c=await currentProject(e),plan={members:structuredClone(p.plan.members),tasks:[]};await modelCatalog.freeze(plan.members,c);const r=await projectTeams.plan(o,c,{...a,plan,policy:p.policy,taskPlanning:'leader'});if(!r.reused)await engine.store.update(r.team.id,o,r.team.revision,t=>{t.profile=a.name;if(p.constraints)t.profileConstraints=p.constraints;});return {kind:'team-detail',...await leader.receipt(o,r.team.id),reused:r.reused,leaderAction:r.team.planReview?.status==='pending'?'Present the team goal and members for confirmation. Do not plan concrete tasks yet.':'Read the selected profile, adapt its constraints and optional seed tasks to the confirmed goal, then add_team_tasks with independent reviews. No individual task confirmation is required.'};}));
nativeTool('prepare_team_worktree','为闲置写入成员准备可选 Git worktree；保留同一原生线程，任务文件操作使用分配目录，无全项目快照。',{...editTeam,memberId:id},async(a,o)=>{await engine.store.update(a.teamId,o,a.revision,async t=>{t.members.find(m=>m.id===a.memberId).workspace=await worktrees.prepare(t,a.memberId);});return leader.receipt(o,a.teamId);});
nativeTool('integrate_team_worktree','已独立验收且所有写入停止后预检并暂存候选合并；不自动提交，冲突预检不修改主项目。',{...editTeam,memberId:id},async(a,o)=>{const saved=await engine.store.update(a.teamId,o,a.revision,async t=>{const integration=await worktrees.integrate(t,a.memberId);t.integrations??=[];if(!t.integrations.some(i=>i.memberId===integration.memberId&&i.candidate===integration.candidate))t.integrations.push(integration);return integration;});return {...await leader.receipt(o,a.teamId),integration:saved.result};});
nativeTool('record_team_peer_delivery','记录 Leader 通过原生工具转交团队成员消息的真实结果；未知送达不能自动重发。',{...editTeam,messageId:z.string().uuid(),status:z.enum(['host-accepted','unknown','failed']),note:z.string().min(1).max(2000)},async(a,o)=>{await engine.store.update(a.teamId,o,a.revision,t=>recordPeerDelivery(t,a));return leader.receipt(o,a.teamId);});
async function participant(extra,tid){const context=await currentProject(extra),saved=await engine.store.document(tid).read();if(!saved.id)throw new Error('Team not found');const t=await engine.store.get(tid,saved.ownerId),member=t.members.find(m=>m.agentThreadId===context.threadId);if(context.cwd!==t.projectPath||!(context.threadId===t.leaderThreadId||(member&&context.parentThreadId===t.leaderThreadId)))throw new Error('Only an authenticated native team participant can access its mailbox');return {team:t,member,context,owner:t.ownerId};}
registerAppTool(server,'read_member_team_work',{description:'当前真实原生成员只读自己被分配的任务、就绪条件和下一步，不领取其他成员工作。',inputSchema:teamId,annotations:readOnly,_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const p=await participant(e,a.teamId);const work=memberWork(p.team,p.context),task=p.team.tasks.find(t=>t.memberId===p.member?.id&&t.status==='running');return {...work,efficiency:efficiencyAdvice(task?.attempts.at(-1)?.observation)};}));
registerAppTool(server,'read_team_source',{description:'Read a bounded selected project source page. Stable cursor rejects changed content; no binary files or symlink escape. Member can read only current own/dependency task source.',inputSchema:{...teamId,taskId:id,path:z.string().min(1).max(300),startLine:z.number().int().positive().default(1),maxChars:z.number().int().min(256).max(6000).default(4000),cursor:z.string().regex(/^[a-f0-9]{64}$/).optional()},annotations:readOnly},guarded(async(a,e)=>{const p=await participant(e,a.teamId);return readTeamSource(p.team,p.context,a);}));
registerAppTool(server,'prepare_team_command',{description:'Prepare a native command with durable logs, a pre-command input fingerprint and 1200-token output cap. Add verificationInputs for configs/fixtures beyond contract scope. Does not execute, verify or start a model; caller executes exact returned command once in workspace and retains real exit code.',inputSchema:{...teamId,taskId:id,attemptId:z.string().uuid(),requestId:z.string().uuid(),command:z.string().min(1).max(4000),verificationInputs:z.array(z.string().min(1).max(2000)).max(6000).default([])},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false}},guarded(async(a,e)=>{const p=await participant(e,a.teamId);return prepareTeamCommand(leader.root,p.team,p.context,a);}));
registerAppTool(server,'read_team_command_log',{description:'Read at most 6000 characters from one registered command log at a byte offset; preserves full logs on disk. Only original task or authenticated dependency evidence. No synthetic exit codes.',inputSchema:{...teamId,taskId:id,attemptId:z.string().uuid(),requestId:z.string().uuid(),offset:z.number().int().min(0).default(0),maxChars:z.number().int().min(256).max(6000).default(2000)},annotations:readOnly},guarded(async(a,e)=>{const p=await participant(e,a.teamId);return readTeamCommandLog(leader.root,p.team,p.context,a);}));
registerAppTool(server,'read_team_peer_message',{description:'Page one oversized original recipient message without acknowledging a partial read. Read all required pages, then acknowledge its original ID separately. Member identity and exact recipient turn are required.',inputSchema:{...teamId,messageId:z.string().uuid(),attemptId:z.string().uuid().optional(),offset:z.number().int().min(0).default(0),maxChars:z.number().int().min(256).max(2000).default(2000),cursor:z.string().regex(/^[a-f0-9]{64}$/).optional()},annotations:readOnly},guarded(async(a,e)=>{const p=await participant(e,a.teamId),task=p.team.tasks.find(t=>t.memberId===p.member?.id&&t.status==='running'&&t.attempts.at(-1)?.id===a.attemptId),attempt=task?.attempts.at(-1);if(p.member&&!attempt?.turnId)throw new Error('A bound current recipient attempt is required');return {kind:'peer-message-page',...peerMessagePage(p.team,p.context.threadId,{...a,turnId:attempt?.turnId})};}));
registerAppTool(server,'consume_team_inbox',{description:'Read and acknowledge only pending actionable messages for this exact authenticated recipient attempt in one transaction. Bounded page; preserves full history, skips progress and old attempts. Leader may omit attemptId.',inputSchema:{...teamId,attemptId:z.string().uuid().optional(),after:z.number().int().min(0).default(0)},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false}},guarded(async(a,e)=>{
 const p=await participant(e,a.teamId),task=p.team.tasks.find(t=>t.memberId===p.member?.id&&t.status==='running'&&t.attempts.at(-1)?.id===a.attemptId),attempt=task?.attempts.at(-1);
 if(p.member&&!attempt?.turnId)throw new Error('A bound current recipient attempt is required');
 const input={after:a.after,attemptId:a.attemptId,turnId:attempt?.turnId},page=pendingPeerInbox(p.team,p.context.threadId,input);
 if(!page.messages.length)return {kind:'peer-inbox',revision:p.team.revision,...page};
 const r=await engine.store.update(a.teamId,p.owner,p.team.revision,t=>{const selected=pendingPeerInbox(t,p.context.threadId,input);for(const m of selected.messages)acknowledgePeerMessage(t,{messageId:m.id,threadId:p.context.threadId,turnId:attempt?.turnId,attemptId:a.attemptId});return selected;});return {kind:'peer-inbox',revision:r.team.revision,...r.result,acknowledged:true};
}));
registerAppTool(server,'claim_member_team_task',{description:'真实成员在现有原生轮次领取自己就绪的任务。稳定 UUID 去重，检查依赖、预算、并发和独立审查；返回公开回执 marker，继续当前轮次，禁止自行 spawn/followup。',inputSchema:{...editTeam,taskId:id,requestId:z.string().uuid()},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const p=await participant(e,a.teamId);return leader.memberClaim(p.owner,a.teamId,a.revision,p.context,a);}));
registerAppTool(server,'bind_member_team_task',{description:'成员公开发出自己领取任务的 marker 后，绑定当前真实原生线程；只能绑定自己的任务，不允许指定其他线程或替换成员。',inputSchema:{...editTeam,taskId:id,attemptId:z.string().uuid()},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const p=await participant(e,a.teamId),r=await leader.memberBind(p.owner,a.teamId,a.revision,p.context,a);return {kind:'member-binding',teamId:a.teamId,revision:r.team.revision,taskId:a.taskId,attemptId:a.attemptId};}));
registerAppTool(server,'report_member_team_task',{description:'成员为自己当前已绑定轮次保存进度、证据和可选交付草稿；明确标记 authenticated-member。提交后仍须输出公开最终交付，只有宿主终态核实后才进入独立审查，不接受成员自验收。',inputSchema:{...editTeam,taskId:id,attemptId:z.string().uuid(),requestId:z.string().uuid(),summary:z.string().trim().min(1).max(3000),decisions:z.array(z.string().min(1).max(2000)).max(30).default([]),remainingWork:z.array(z.string().min(1).max(2000)).max(30).default([]),evidence:z.array(z.string().min(1).max(2000)).max(30).default([]),validation:z.array(z.object({name:z.string().min(1).max(2000),status:z.enum(['PASS','FAIL','BLOCKED','NOT_RUN']),evidence:z.string().min(1).max(2000)})).max(30).default([]),delivery:z.string().min(1).max(24000).optional(),handoff:z.boolean().optional(),verificationInputs:z.array(z.string().min(1).max(300)).max(30).optional()},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const p=await participant(e,a.teamId);return leader.memberReport(p.owner,a.teamId,a.revision,p.context,a);}));
registerAppTool(server,'send_team_peer_message',{description:'原生成员为当前任务保存给队友或 Leader 的持久消息；Leader 保留实际原生发送控制，保存不等于送达。',inputSchema:{...teamId,attemptId:z.string().uuid(),toMemberId:id,text:z.string().min(1).max(4000),requestId:z.string().uuid(),kind:z.enum(['action','blocker','completion','progress']).default('action')},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const p=await participant(e,a.teamId);if(!p.member)throw new Error('Use the Leader mailbox tool for Leader messages');const r=await engine.store.update(a.teamId,p.owner,p.team.revision,t=>{const before=t.peerMessages?.length??0,message=queuePeerMessage(t,{...a,senderMemberId:p.member.id,senderThreadId:p.context.threadId});return {message,firstOffer:t.peerMessages.length>before};});const message=r.result.message;return {kind:'peer-message',revision:r.team.revision,message:peerReceipt(message),delivery:'saved-not-sent',nativeAction:r.result.firstOffer&&message.kind!=='progress'?{tool:'send_message',target:message.toMemberId==='leader'?p.member.agentPath?.slice(0,p.member.agentPath.lastIndexOf('/')):r.team.members.find(m=>m.id===message.toMemberId)?.agentPath,threadId:message.recipientThreadId,text:message.marker+'\n'+message.text}:null};}));
registerAppTool(server,'read_team_inbox',{description:'读取当前真实团队参与者的持久收件箱，不能读取其他成员的私有目标收件箱。',inputSchema:{...teamId,after:z.number().int().min(0).default(0)},annotations:readOnly,_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const p=await participant(e,a.teamId);const task=p.team.tasks.find(t=>t.memberId===p.member?.id&&t.status==='running'),attempt=task?.attempts.at(-1);return {kind:'peer-inbox',...(responseContext.getStore()?pendingPeerInbox(p.team,p.context.threadId,{...a,attemptId:attempt?.id,turnId:attempt?.turnId}):peerInbox(p.team,p.context.threadId,a))};}));
registerAppTool(server,'acknowledge_team_peer_message',{description:'原收件成员确认已从收件箱读取指定消息；记录真实原生线程和其当前任务轮次，不代替业务完成。',inputSchema:{...teamId,messageId:z.string().uuid(),attemptId:z.string().uuid().optional()},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const p=await participant(e,a.teamId),task=p.team.tasks.find(t=>t.memberId===p.member?.id&&t.status==='running'&&t.attempts.at(-1)?.id===a.attemptId),attempt=task?.attempts.at(-1);if(p.member&&!attempt?.turnId)throw new Error('A bound current recipient attempt is required');const r=await engine.store.update(a.teamId,p.owner,p.team.revision,t=>acknowledgePeerMessage(t,{messageId:a.messageId,threadId:p.context.threadId,turnId:attempt?.turnId,attemptId:a.attemptId}));return {kind:'peer-acknowledgement',message:peerReceipt(r.result),revision:r.team.revision};}));
registerAppTool(server,'read_team_context',{description:'按需读取一个任务。compact 保留完整目标/合同和验收条件；full 返回交接原文。evidence 分页读取指定 attempt 的交付、命令列表、单条命令或输出，默认4000字符，上限8000；hasMore=true 必须继续读所需完整证据后验收。原记录不截断，cursor 防止混用不同结果。',inputSchema:{...teamId,taskId:id,view:z.enum(['compact','full','evidence']).default('compact'),attemptId:z.string().uuid().optional(),section:z.enum(['delivery','commands','command','command-output','checkpoint','verification','review-registration']).default('delivery'),commandIndex:z.number().int().min(0).optional(),offset:z.number().int().min(0).default(0),limit:z.number().int().min(512).max(8000).default(4000),cursor:z.string().regex(/^[a-f0-9]{64}$/).optional()},annotations:readOnly,_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const p=await participant(e,a.teamId);if(p.member){const own=p.team.tasks.find(t=>t.memberId===p.member.id&&t.status==='running');const allowed=new Set();function include(id){if(allowed.has(id))return;allowed.add(id);for(const d of p.team.tasks.find(t=>t.id===id)?.dependencies??[])include(d.taskId);}if(own)include(own.id);if(!allowed.has(a.taskId))throw new Error('Only the current task and its dependency contexts may be read');}if(a.view==='evidence')return evidencePage(p.team,a);const {team,handoff}=await leader.handoff(p.owner,a.teamId,a.taskId);return {kind:'team-context',handoff:a.view==='full'?handoff:compactHandoff(handoff,normalizePolicy(team.policy))};}));
registerAppTool(server,'read_team_usage',{description:'读取当前团队时间范围的真实处理量，包含 Leader 和经父级/项目验证的直接原生成员；兜底上下文只记成本，不自动绑定任务。summary 不复制历史任务，full 按需查看分项；未知保留未知，缓存输入不等于账单。派发预算另行强制实时核对。',inputSchema:{...teamId,view:z.enum(['summary','full']).default('summary'),refreshHistorical:z.boolean().default(false)},annotations:readOnly,_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const report=await leader.usage(await assertCurrentTeam(e,a.teamId),a.teamId,a);if(a.view==='summary'){const {tasks,contexts,...usage}=report;return {kind:'team-usage',usage,detailsAccess:{tool:'read_team_usage',view:'full',teamId:a.teamId}};}return {kind:'team-usage',usage:report};}));
registerAppTool(server,'record_team_peer_sender_delivery',{description:'原消息发送成员记录自己调用原生消息工具的实际回执；只限自己当前任务的消息，保存或工具成功不等于成员已读。',inputSchema:{...teamId,messageId:z.string().uuid(),status:z.enum(['host-accepted','unknown','failed']),note:z.string().min(1).max(2000)},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false},_meta:{ui:{visibility:['app','model']}}},guarded(async(a,e)=>{const p=await participant(e,a.teamId),message=p.team.peerMessages?.find(m=>m.id===a.messageId);if(!p.member||message?.senderThreadId!==p.context.threadId)throw new Error('Only the original sender can record its delivery');const task=p.team.tasks.find(t=>t.id===message.taskId);if(task?.attempts.at(-1)?.id!==message.attemptId||task.status!=='running')throw new Error('Original sender attempt is no longer active');const r=await engine.store.update(a.teamId,p.owner,p.team.revision,t=>recordPeerDelivery(t,{...a,source:'authenticated-sender-native-tool'}));return {kind:'peer-delivery',message:peerReceipt(r.result),revision:r.team.revision};}));
nativeTool('bind_team_roster_member','岗位与当前原生执行会话一对一绑定；旧任务会话按代次保留。按 plan 返回的初始化提示创建成员，立即传宿主返回的路径；初始化回执未落盘时保留关联，不能重建。新任务按派发包创建隔离会话；活动或未知轮次不能替换。',{...editTeam,memberId:id,threadId:z.string().min(1).max(200)},(a,o)=>leader.bindRoster(o,a.teamId,a.revision,a.memberId,a.threadId));
