 if(a.operation==='capabilities')return {kind:'team-capabilities',compactAdvancement:true,selectedEvidenceDefault:true,registrationGapNotice:true,schemaReuse:'explicit-versioned-hash',boundedSourceAndLogPages:true,nativeCommandLogPreparation:true,preCommandInputFingerprint:true,hostWorkingDirectoryVerification:true,historicalVerificationReconciliation:'explicit-native-command-identities-and-unchanged-inputs',commandCapsEnforcement:'helpers-and-dispatch-instructions; direct-native-tools-remain-host-controlled',phaseHandoff:'explicit-completed-checkpoint; max-3; clean-context',phaseVerificationReuse:'successful-host-command-and-unchanged-input-fingerprint',progressWakeCoalescing:true,persistentSemanticWaitCursor:true,declaredInitializationBinding:true,singleWaitWithInlineCoordination:true,combinedInboxAcknowledgement:true,singleCopyRouterPayload:true,singleCopyModelPayloads:true,source:'current-adapter-contract',nativeToolsRequired:true,workflowBridge:'disabled',internalCommunication:'native-agent-messages-and-completions',panelControlWait:'wait_team_event',nativeTerminalEventWait:true,panelWakeWithoutWaiter:false,chatMessages:false,backgroundModelExecutor:false,existingMemberModelChange:false,arbitraryProviderRouting:false,nativeSlashMenuRegistration:false,nativeHeaderSlot:false,nativeTurnAnchor:false,crossLeaderControlTransfer:false,restartControlRestoration:'requires-real-native-tool-receipt',preservesOriginalMemberIdentity:false,preservesLogicalRoleIdentity:true,preservesNativeExecutionHistory:true,taskContextIsolation:true,inPlaceContextReset:false,dispatchContextBudget:'full-prompt-hard-limit',modelCoordinationView:'coordination',unchangedTimeoutRequiresStateRead:false,reviewerAcceptance:'plugin-gated-on-settlement',leaderReviewScope:'exceptions-and-final-closure',finalEvidenceReuse:'accepted-integration-contract-with-unchanged-inputs',evidencePageMaxChars:8000,usageScope:'leader-and-direct-native-children-during-team',usageDisplayCacheMs:10000,budgetVerification:'fresh-before-plugin-dispatch',fallbackContextsExecutionAuthority:false};
 if(a.operation==='history'){const rows=await engine.store.summaries(o,c.cwd),current=await projectTeams.current(o,c);return {kind:'team-history',teams:rows.slice(a.offset,a.offset+a.limit).map(t=>({...t,readOnly:t.id!==current?.id})),total:rows.length,nextOffset:rows.length>a.offset+a.limit?a.offset+a.limit:null,currentTeamId:current?.id};}
 if(a.operation==='profiles')return {kind:'team-profiles',profiles:await profiles.read()};
